    Double.fromBits(imguiKmpReadI32(ptr + byteOffset, 0).toUInt().toLong() or (imguiKmpReadI32(ptr + byteOffset + 4, 0).toLong() shl 32))

private fun readUtf8(ptr: Int, max: Int): String {
    var end = 0
    while (end < max && imguiKmpReadU8(ptr, end) != 0) end++
    return ByteArray(end) { imguiKmpReadU8(ptr, it).toByte() }.decodeToString()
}

