    actual fun fontsAddFontDefaultConfig(atlas: Long, name: String?, mergeMode: Boolean, pixelSnapH: Boolean, oversampleH: Int, oversampleV: Int, sizePixels: Float, glyphOffsetX: Float, glyphOffsetY: Float, glyphMinAdvanceX: Float, glyphMaxAdvanceX: Float, rasterizerMultiply: Float, rasterizerDensity: Float, extraSizeScale: Float): Long {
        val s1 = imguiKmpAllocString(name)
        try {
            return imgui_font_atlas_add_font_default_cfg(atlas.toInt(), s1, if (mergeMode) 1 else 0, if (pixelSnapH) 1 else 0, oversampleH, oversampleV, sizePixels, glyphOffsetX, glyphOffsetY, glyphMinAdvanceX, glyphMaxAdvanceX, rasterizerMultiply, rasterizerDensity, extraSizeScale).toLong()
