    actual fun fontsAddFontFromFileTTFConfig(atlas: Long, path: String, name: String?, mergeMode: Boolean, pixelSnapH: Boolean, oversampleH: Int, oversampleV: Int, sizePixels: Float, glyphOffsetX: Float, glyphOffsetY: Float, glyphMinAdvanceX: Float, glyphMaxAdvanceX: Float, rasterizerMultiply: Float, rasterizerDensity: Float, extraSizeScale: Float): Long {
        val s1 = imguiKmpAllocString(path)
        val s2 = imguiKmpAllocString(name)
        try {
            return imgui_font_atlas_add_font_from_file_ttf_cfg(atlas.toInt(), s1, s2, if (mergeMode) 1 else 0, if (pixelSnapH) 1 else 0, oversampleH, oversampleV, sizePixels, glyphOffsetX, glyphOffsetY, glyphMinAdvanceX, glyphMaxAdvanceX, rasterizerMultiply, rasterizerDensity, extraSizeScale).toLong()
        } finally {
            imguiKmpFree(s1)
            imguiKmpFree(s2)
        }
    }
    actual fun fontsAddFontFromFileTTFRanges(atlas: Long, path: String, name: String?, mergeMode: Boolean, pixelSnapH: Boolean, oversampleH: Int, oversampleV: Int, sizePixels: Float, glyphOffsetX: Float, glyphOffsetY: Float, glyphMinAdvanceX: Float, glyphMaxAdvanceX: Float, rasterizerMultiply: Float, rasterizerDensity: Float, extraSizeScale: Float, glyphRanges: IntArray): Long {
        val s1 = imguiKmpAllocString(path)
        val s2 = imguiKmpAllocString(name)
        val a15 = imguiKmpMalloc(glyphRanges.size * 4)
        imguiKmpSetHeapI32(a15, glyphRanges.toInt32Array())
        try {
            return imgui_font_atlas_add_font_from_file_ttf_ranges(atlas.toInt(), s1, s2, if (mergeMode) 1 else 0, if (pixelSnapH) 1 else 0, oversampleH, oversampleV, sizePixels, glyphOffsetX, glyphOffsetY, glyphMinAdvanceX, glyphMaxAdvanceX, rasterizerMultiply, rasterizerDensity, extraSizeScale, a15).toLong()
        } finally {
            for (i in glyphRanges.indices) glyphRanges[i] = imguiKmpReadI32(a15, i)
            imguiKmpFree(s1)
            imguiKmpFree(s2)
            imguiKmpFree(a15)
        }
    }
